void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;

    // Scroll
    uv.y = uv.y + iTime * 0.1;

    // Scale y
    uv *= 16.0;

    // Segment y
    uv.y = fract(uv.y);

    float color = step(0.1, uv.y);

    // Output to screen
    fragColor = vec4(vec3(color),1.0);
}
